%[text] # Vector Demo
%[text] A notation convention
%[text] - Scalars are lower case: `x`
%[text] - Vectors (1-D arrays) are double letters: `xx`
%[text] - Matrices (2-D arrays) are capitals: `X` \
%[text] ## Creation
%[text] As an vector with step size = 1
xx = 1:5
size(xx)
%%
%[text] As a list with step size ~= 1
yy = 1:3:10
%%
%[text] As an N-by-1 column of zeros
zz = zeros(5,1)
zz = zeros(5)
%%
%[text] As a 1-by-N row of ones
oo  = ones(1,5)
ff = 5*ones(1,5)
%%
%[text] A vector (1-by-N row) of psuedorandom numbers
rr = rand(1,5)
%%
%[text] Manually, as a row vector, with and without commas.
mm = [5 3.1 9.8 -2]

nn = [5, 3.1, 9.8, -2]
%%
%[text] Manually as a column vector
cc = [5; 3.1; 9.8; -2;]
% As a column using transpose
dd = [5 3.1 9.8 -2]'
%%
%[text] Linear spacing from A to B with N elements
ll = linspace(0, 1, 101)
mm = 0:0.5:1
%%

%[text] Logrithmic spacing from 10^A to 10^B with N elements
pp = logspace(-2, 2, 5)
%%
%[text] ### Exercises
%[text] Find a comand to create the following vectors
%[text] ![](text:image:2d13)
42*ones(1,4)
%[text] ![](text:image:2b40)

%[text] ![](text:image:1e89)
%[text] ![](text:image:1db5)

%[text] ![](text:image:6c4a)

%%
%[text] ## Indexing and Slicing
%[text] Given a vector...
aa = 10:10:100
%%
%[text] Access an element by its index
aa(4)
aa(5) = 3.14

%%
%[text] Slice a vector with a vector of indices
aa(1:3)
%%
aa(8:end)
aa(end-3:end)
%%
aa([3 5 7])
%%
%[text] Modifying an element
aa(3) = 0
%%
%[text]  or elements
aa([1 5]) = -1
aa([2 4]) = [-2 -3]
%%
%[text] ### Exercises
%[text] Given `bb`, extact all the elements in odd-numberd positions.
bb = 1:9
b_slice = bb([1,3,5,7])
bb

bb([1,3,5,7]) = -1
%[text] Given `cc` , using indexing create a new vector that reverses the order of the elements
cc = [5 10 15 20]
size(cc,2)
c_rev = [];
for ii = 1:size(cc, 2)
    disp(cc(ii))
end

c_rev = [cc(end) cc(end-1) cc(end-2)]
c_ref = cc(end:-1:1)
%[text] Given `dd`, **find** the index of the elements with value equal to -1.0
dd = sin((0:7) * pi / 2)

%[text] **find** the indices for all the elements of `dd` wtih value equal to 1.0

%%
%[text] ## Array vs Matrix Operations
%[text] ![](text:image:5479)
%[text] [Link](https://www.mathworks.com/help/matlab/matlab_prog/array-vs-matrix-operations.html)
%[text] For now we want to use only element-wise array operations by prepending the math symbol with a period.
aa = [1 2]
%[text] Addition/Subtraction
bb = aa+10
cc = aa-bb
%%
%[text] Multiplication/Division
%[text] Multiply by a scalar
aa
dd = aa*0.1
%[text] Element-wise multiplication
dd
aa
aa
dd
ee = dd.*aa
%[text] but this throws an errror!
%[text] ![](text:image:35cb)
dd = ee./aa
%%
%[text] Exponents
%[text] Scalar exponent
ff = [1 2 4];
gg = ff.^2
%[text] Element-wise exponent
gg = [-1 1 -1];
hh = ff.^gg
%[text] but this throws an errror!
%[text] ![](text:image:63e4)
%%
%[text] ### Idiom: Plotting a 2D Function with Vectors
%[text] Model: Plot the function
%[text] $y(x) = x \\, sin(x)$
%[text] for  $0 \\leq x \\leq 2 \\pi$
% Define x values using linspace
xx = linspace(0, 2*pi, 100);

% Compute y using element-wise operations (note the .*)
yy = xx .* sin(xx);

% Plot
plot(xx, yy, 'LineWidth', 2)
xlabel('x')
ylabel('y')
title('Example: y(x) = x .* sin(x)')
grid on
%%
%[text] ### Growing an array
% Make an array with one element
clear aa
aa(1) = 10;

% Grow the array one element at a time
for ii = 2:10
    aa(ii) = aa(ii-1)*0.9;
end
plot(aa, "r--o")

